import gymimport jsonimport pickleimport warningsimport pandas as pdfrom stable_baselines.common.policies import MlpPolicyfrom stable_baselines.common.vec_env import DummyVecEnvfrom stable_baselines import PPO2, TD3from src.environment import DataFrameEnvfrom src.bounds import get_bounds_limitswarnings.filterwarnings("ignore")# env settingsseed = 0env_name = "TabularOptimization"file_name = "%s_%s_%s" % ("TD3", env_name, str(seed))# dataframe training environmentdf = pd.read_csv("data/data_energy_train.csv")test_df = pd.read_csv("data/data_energy_test.csv")# dataframe atributestarget = "pe"control_variables = ["at", "v"]features = list(df.columns)features.remove(target)print("features /  Action Space: ", features)print("control_variables: ", control_variables)print("target: ", target)max_episodes = int(100)# load model environmentpath_model = "env_model/model_env.pkl"with open(path_model, "rb") as file:    model = pickle.load(file)# bounds limits for variablesbounds = get_bounds_limits(df)# configuración del entornoenv = DataFrameEnv(df, model, features, control_variables, target, bounds)# The algorithms require a vectorized environment to runenv = DummyVecEnv([lambda: env])# actor critic agentsagent = PPO2(MlpPolicy, env, verbose=1, tensorboard_log="./tensorboard/")agent.learn(total_timesteps=max_episodes)# configuración del entornotest_env = DataFrameEnv(test_df, model, features, control_variables, target, bounds)env = DummyVecEnv([lambda: test_env])obs = test_env.reset()results = pd.DataFrame()for i in range(len(test_env.df)):    action, _states = agent.predict(obs)    obs, rewards, done, info = test_env.step(action)    print(rewards)    test_env.render()    action_df = pd.DataFrame(action, columns=["rec_" + i for i in control_variables])    obs_df = pd.DataFrame(obs, columns=features)    rewards_df = pd.DataFrame([rewards], columns=["rewards"])    real_value = pd.DataFrame([test_df.iloc[test_env.current_step]], columns=["value"])    di = pd.concat([action_df, obs_df, rewards_df], axis=1)    results = pd.concat([results, di], axis=0)    results.reset_index(drop=True, inplace=True)print("Average rewards: ", results["rewards"].mean(), "[%]")rec_control_variables = ["rec_" + i for i in control_variables]context_variables = test_env.context_variablesresults["optimized"] = test_env.model.predict(results[rec_control_variables + context_variables])results["prediction"] = test_env.model.predict(results[features])results["real"] = test_df[target]results["uplift"] = (results["optimized"] - results["real"]) / results["real"] * 100print("Uplift: ", results["uplift"].mean(), "[%]")